import * as PIXI from 'pixi.js';
import RBush from 'rbush';
import { LayerBatches } from './lib/LayerBatches.ts';
import { Extent, WORLD_ZOOM } from '@rapid-sdk/math';
import { extentMinus, featureOrder } from './helpers.ts';
import { makeDataID, splitDataID } from '../data/dataID.ts';
import { type OneOrMore, utilIterable } from '../util/iterable.ts';

import type { AbstractData } from '../data/AbstractData.ts';
import type { AbstractPixiFeature } from './AbstractPixiFeature.ts';
import type { BBox } from 'rbush';
import type { Context } from '../Context.ts';
import type { SpatialChange } from '../core/SpatialSystem.ts';
import type { Viewport } from '@rapid-sdk/math';
import type { GraphicsSystem } from '../core/GraphicsSystem.ts';
import type { LayerWork, RenderFrame } from './RenderFrame.ts';
import type { PixiScene } from './PixiScene.ts';


/** How many passes a feature can go unseen before `cull()` destroys it */
const KEEP_UNSEEN_PASSES = 20;

/**
 * How many moves of the cull box (or passes) a hidden feature is kept for before it's destroyed,
 * in a layer that follows the box without a pass (see `_forgetHidden`). Panning back within that
 * many finds it still made.
 */
const KEEP_HIDDEN_MOVES = 20;

/**
 * `continueWaiting()` draws at least this many of the features that are waiting, on each call,
 * even in a frame that's out of time. So the work gets done however slow the frames are.
 */
const MIN_WAITING_PER_FRAME = 32;

/**
 * While the view moves, the work waiting outside it is looked at this often (ms), for what has
 * come into view (see `_sortWaiting`). Not on every frame: it's a walk over everything waiting.
 */
const SORT_WAITING_MS = 100;

/**
 * What drawing a feature costs later, in the frame's DRAW phase, in milliseconds. Pixi builds a
 * shape's geometry when it first renders it, so a feature that's new or has changed costs more
 * there than one drawn again after a zoom. Measured Nov 2026 on an M4 at Staten Island: a
 * restyle of 18,500 features took 34 ms of DRAW (2 µs each), and new features 5 µs each when a
 * few hundred were made in a frame, but 30 µs each when 7,000 were (212 ms).
 * They don't need to be exact: they keep one frame from drawing thousands of features in a few
 * milliseconds of APP phase, and then spending a quarter of a second in DRAW.
 */
const DRAW_MS_PER_REDRAW = 0.004;
const DRAW_MS_PER_NEW = 0.01;

/**
 * Pixels added to the furthest a feature can be hit from the box of its geometry (`hitReach`),
 * when a layer looks for the features near the pointer (see `hitTest`). The pointer and the
 * features are placed by the frame that was drawn.
 */
export const HIT_REACH_MARGIN = 4;


/** Where a feature drawn in the layer's batches is, in world coordinates, for `hitTest` to find it */
interface FeatureBox extends BBox {
  feature: AbstractPixiFeature;
  /** The spatial ID of the container it's drawn for, which the mode may keep the pointer from */
  spatialID: SpatialID;
}


/**
 * AbstractPixiLayer is the base class from which all rendering Layers inherit.
 * It creates a container to hold the Layer data.
 *
 * Notes on identifiers:
 * All identifiers should be strings, to avoid JavaScript comparison surprises (e.g. `'0' !== 0`)
 * - `layerID`   - A unique identifier for the layer, for example 'osm'
 * - `featureID` - A unique identifier for the feature, for example 'osm-w-123-fill'
 * - `dataID`    - A feature may have data bound to it, by its data ID, for example 'w-123' or 'fbRoads:abc'
 * - `classID`   - A pseudoclass identifier like 'hover' or 'select'
 *
 * Properties available:
 * - `id` (or `layerID`) - A unique identifier for the layer, for example 'osm'
 * - `supported`         - Is this Layer supported? (i.e. do we even show it in lists?)
 * - `zIndex`            - Where this Layer sits compared to other Layers
 * - `enabled`           - Whether the the user has chosen to see the Layer
 * - `features`          - `Map<featureID, Feature>` of all features on this Layer
 * - `retained`          - `Map<featureID, Integer pass>` last seen
 *
 * A layer's work for a frame is one "pass": `render()` gathers the data the frame needs, updates its
 * features and marks them seen (`retainFeature`), then `cull()` hides the features that weren't seen.
 * A layer whose `render()` calls `keepFeatures()` skips the pass on frames where only the view moved
 * (see "The cull box" in `design/graphics-system.md`).
 */
export class AbstractPixiLayer {

  /** Unique identifier for this Layer */
  public id: LayerID;
  /** The Scene that owns this Layer */
  public scene: PixiScene;
  /** Reference to the GraphicsSystem */
  public gfx: GraphicsSystem;
  /** Global shared application context */
  public context: Context;
  /** Map of featureID to Feature */
  public features: Map<FeatureID, AbstractPixiFeature>;
  /** Map of featureID to the pass it was last seen in */
  public retained: Map<FeatureID, number>;
  /** What the layer has done since `takeWork()`, for the frame's stats (its features count into it too) */
  public work: LayerWork;

  /** Whether the user has chosen to see the layer */
  protected _enabled: boolean;
  /** The number of the current pass: `retainFeature()` marks features with it, and `cull()` ends it */
  protected _pass: number;
  /** The cull box the layer's features are current for, or `null` if they need a pass (see `keepFeatures`) */
  protected _currentBox: Extent | null;
  /** The frame in which `keepFeatures()` last said to do a pass */
  protected _passFrame: number;
  /** The frame in which `keepFeatures()` last said to keep the features */
  protected _keptFrame: number;
  /** Dirty features in view that `updateFeature()` put off, to be drawn again in the coming frames */
  protected _waitingInView: Set<AbstractPixiFeature>;
  /** Dirty features outside the view (in the cull box's padding), drawn again when a frame has time to spare */
  protected _waitingOutside: Set<AbstractPixiFeature>;
  /** Features that were drawn and are still dirty: a texture of theirs hasn't loaded (see `texturesLoaded`) */
  protected _waitingForTexture: Set<AbstractPixiFeature>;
  /** The view (`frame.viewBox`) that the waiting work was last sorted by, into in view and outside */
  protected _sortedBox: Extent | null;
  /** When the waiting work was last sorted again (`frame.time`, see `_sortWaiting`) */
  protected _sortedTime: number;
  /** How many of the layer's features are visible (kept by `AbstractPixiFeature`, see `numVisible`) */
  protected _numVisible: number;
  /** The furthest that any feature drawn since the last reset can be hit from its geometry's box, in pixels (`AbstractPixiFeature.hitReach`) */
  protected _hitReach: number;
  /**
   * Whether the layer is making features after its pass has ended (in a later frame, or after
   * `cull()`), for data that the pass put off. `retainFeature()` then counts them as seen by that pass.
   */
  protected _catchingUp: boolean;
  /** Map of featureID to dataID */
  protected _featureHasData: Map<FeatureID, DataID>;
  /** Map of dataID to Set of featureIDs */
  protected _dataHasFeature: Map<DataID, Set<FeatureID>>;
  /** Map of parent dataID to Set of child dataIDs */
  protected _parentHasChildren: Map<DataID, Set<DataID>>;
  /** Map of child dataID to Set of parent dataIDs */
  protected _childHasParents: Map<DataID, Set<DataID>>;
  /** Spatial IDs this layer has containers for (see `_spatialContainer`) */
  protected _spatialIDs: Set<SpatialID>;
  /** The spatial ID of each container from `_spatialContainer` */
  protected _spatialIDOf: Map<PIXI.Container, SpatialID>;
  /** The features drawn in the layer's batches, by where they are, for `hitTest` */
  protected _featureIndex: RBush<FeatureBox>;
  /** The box of each feature in `_featureIndex` */
  protected _indexedBoxes: Map<AbstractPixiFeature, FeatureBox>;
  /** The container that each feature is drawn for, by a layer that draws in batches (see `updateFeature`) */
  protected _parentOf: Map<AbstractPixiFeature, PIXI.Container>;
  /** How many times the cull box moved, or a pass was done: hidden features age by this (see `_forgetHidden`) */
  protected _moves: number;
  /** The features that are hidden, and the value of `_moves` when each was */
  protected _hiddenAt: Map<FeatureID, number>;
  /** Whether the cull box moved since what it left behind was last hidden (see `cullLater`) */
  protected _cullDue: boolean;
  /** Where data that the layer draws arrived, or moved from, since it last looked (see `spatialChanged`) */
  protected _arrivedBoxes: Extent[];
  /** The data that was replaced or removed since the layer last looked (see `spatialChanged`) */
  protected _arrivedIDs: Set<DataID>;
  /** Features of replaced or removed data, to hide if the frame's gathering doesn't find them again */
  protected _unconfirmed: Set<AbstractPixiFeature>;

  /**
   * Whether the layer's lines, polygons and points are drawn in batches (see `batches`), not
   * by display objects of their own. A layer that sets it finds its own features under the
   * pointer (`hitTest`): Pixi can't see what a batch draws. Set it in the constructor.
   */
  public useBatches: boolean;
  /**
   * The batches that the layer's features are drawn in: one of each kind in a container, made
   * when a feature first needs it (see `updateFeature`, `design/graphics-system.md`).
   */
  public batches: LayerBatches;


  /**
   * @param scene - The Scene that owns this Layer
   */
  public constructor(scene: PixiScene) {
    this.id = '';  // put this first so debug inspect shows it first

    this.scene = scene;
    this.gfx = scene.gfx;
    this.context = scene.context;

    this._enabled = false;  // Whether the user has chosen to see the layer

    // Collection of Features on this Layer
    this.features = new Map<FeatureID, AbstractPixiFeature>();
    this.retained = new Map<FeatureID, number>();
    this.work = { created: 0, destroyed: 0, updated: 0, shown: 0, hidden: 0, steps: {} };

    this._pass = 0;
    this._currentBox = null;
    this._passFrame = -1;
    this._keptFrame = -1;
    this._waitingInView = new Set<AbstractPixiFeature>();
    this._waitingOutside = new Set<AbstractPixiFeature>();
    this._waitingForTexture = new Set<AbstractPixiFeature>();
    this._sortedBox = null;
    this._sortedTime = -Infinity;
    this._numVisible = 0;
    this._hitReach = 0;
    this._catchingUp = false;

    // Feature <-> Data
    // These lookups capture which features are bound to which data.
    this._featureHasData = new Map<FeatureID, DataID>();
    this._dataHasFeature = new Map<DataID, Set<FeatureID>>();

    // The spatial IDs this layer has asked the scene for containers for (released in `reset()`)
    this._spatialIDs = new Set<SpatialID>();
    this._spatialIDOf = new Map<PIXI.Container, SpatialID>();
    this._featureIndex = new RBush<FeatureBox>();
    this._indexedBoxes = new Map<AbstractPixiFeature, FeatureBox>();
    this._parentOf = new Map<AbstractPixiFeature, PIXI.Container>();
    this._moves = 0;
    this._hiddenAt = new Map<FeatureID, number>();
    this._cullDue = false;
    this._arrivedBoxes = [];
    this._arrivedIDs = new Set<DataID>();
    this._unconfirmed = new Set<AbstractPixiFeature>();

    this.useBatches = false;
    this.batches = new LayerBatches(scene.batchShaders);

    // Parent Data <-> Child Data
    // We establish a parent-child data hierarchy (like what the DOM used to do for us)
    // For example, we need this to know which ways make up a multipolygon relation.
    this._parentHasChildren = new Map<DataID, Set<DataID>>();
    this._childHasParents = new Map<DataID, Set<DataID>>();

    // Data <-> Class
    // The Scene holds these, by dataID (see `PixiScene.setClass`)
  }


  /**
   * Unique string to identify this render Layer.
   * @return This layer's unique id
   * @readonly
   */
  public get layerID(): LayerID {
    return this.id;
  }

  /**
   * Is this Layer supported? (i.e. do we even show it in lists?)
   * Can be overridden in a subclass with additional logic.
   * @return `true` if the layer is supported
   * @abstract
   */
  public get supported(): boolean {
    return true;
  }

  /**
   * Whether the user has chosen to see the Layer.
   * Can be overridden in a subclass with additional logic.
   * @return `true` if the user has chosen to see the layer
   * @abstract
   */
  public get enabled(): boolean {
    return this._enabled;
  }
  /** Enables or disables this layer; derived classes may override to perform additional work.
   * @param val - `true` to enable the layer, `false` to disable it
   */
  public set enabled(val: boolean) {
    if (val === this._enabled) return;  // no change
    this._enabled = val;
    this.dirtyLayer();
  }


  /**
   * Whether this Layer draws the given data, so that selecting it can turn this Layer on.
   * A Layer draws the data whose spatial ID is its own ID, unless it overrides this (see `design/data-ids.md`).
   * @param dataID - The data ID, e.g. `osm-notes:123`
   * @return `true` if this Layer draws the data
   */
  public drawsData(dataID: DataID): boolean {
    return splitDataID(dataID)[0] === this.id;
  }


  /**
   * Makes sure this Layer shows the given data, which it draws (see `drawsData`).
   * Turns the Layer on; a Layer that also chooses what it draws overrides this.
   * @param dataID - The data ID
   */
  public showData(dataID: DataID): void {
    this.enabled = true;
  }


  /**
   * Every Layer should have a reset function to replace any Pixi objects and internal state.
   * Override in a subclass with needed logic.
   * @abstract
   */
  public reset(): void {
    this._featureHasData.clear();
    this._dataHasFeature.clear();
    this._parentHasChildren.clear();  // maybe don't clear this (should pseudo dom survive a reset?)
    this._childHasParents.clear();    // maybe don't clear this (should pseudo dom survive a reset?)

    for (const feature of this.features.values()) {
      feature.destroy();
    }

    this.features.clear();
    this.retained.clear();
    this._waitingInView.clear();
    this._waitingOutside.clear();
    this._waitingForTexture.clear();
    this._sortedBox = null;
    this._numVisible = 0;
    this._hitReach = 0;
    this._currentBox = null;

    for (const spatialID of this._spatialIDs) {
      this.scene.releaseSpatialContainers(spatialID);
    }
    this._spatialIDs.clear();
    this._spatialIDOf.clear();
    this._featureIndex.clear();
    this._indexedBoxes.clear();
    this._parentOf.clear();
    this._hiddenAt.clear();
    this._cullDue = false;
    this._arrivedBoxes = [];
    this._arrivedIDs.clear();
    this._unconfirmed.clear();
    this.batches.forget();    // (they were destroyed with the containers they were in)
  }


  /**
   * Returns the container this layer draws the given spatial ID's data into, in the given group
   * (see `PixiScene.getSpatialContainer` and `design/scene.md`). Features go in it, or in
   * sub-containers made under it with `_childContainer`; `reset()` releases it again.
   * @param groupID - The group, e.g. 'basemap' or 'points'
   * @param spatialID - The spatial ID of the data, e.g. 'osm' or 'fbRoads'
   * @return The container
   */
  protected _spatialContainer(groupID: GroupID, spatialID: SpatialID): PIXI.Container {
    const scene = this.scene;

    if (!this._spatialIDs.has(spatialID)) {
      this._spatialIDs.add(spatialID);
      if (this.useBatches) {
        scene.setHitTester(spatialID, this);    // Pixi can't see what a batch draws (see `hitTest`)
      }
    }
    const container = scene.getSpatialContainer(groupID, spatialID);
    this._spatialIDOf.set(container, spatialID);
    return container;
  }


  /**
   * Returns the child container with the given label, making it if needed.
   * Use this for the containers that hold a layer's features (not for a feature's own container).
   * Each has its own render group, so a change to one feature makes Pixi rebuild the instructions
   * of its siblings only (see `PixiScene.worldContainer`).
   * @param parent - The container to look in, itself from `_spatialContainer` or `_childContainer`
   * @param label - The child's label, e.g. 'polygons'
   * @param zIndex - The child's `zIndex` among its siblings, if it's made
   * @return The child container, with `sortableChildren` on
   */
  protected _childContainer(parent: PIXI.Container, label: string, zIndex = 0): PIXI.Container {
    return this.scene.worldContainer(parent, label, zIndex);
  }


  /**
   * Every Layer should have a render function that manages the Features in view.
   * Override in a subclass with needed logic. It will be passed:
   * @param frame - The frame being rendered
   * @param viewport - Pixi viewport to use for rendering
   * @abstract
   */
  public render(frame?: RenderFrame, viewport?: Viewport): void {
  }


  /**
   * Whether the layer can leave its features exactly as the last frame had them. That's so when
   * nothing that concerns this layer asked for the frame, only a move of the view
   * (`frame.changedFor()`), and the layer already made everything in the frame's cull box
   * (`frame.cullBox`) in an earlier pass. It's also so in a held frame (`frame.held`), where the pass
   * is put off: the layer keeps what it has until a frame that may do the pass.
   *
   * A layer that gathers its data by `frame.cullBox` calls this from `render()`, once it knows it has
   * something to draw and before it gathers anything, and returns if the answer is `true`. `cull()`
   * then leaves the features alone too. If the answer is `false`, the layer must do the whole pass.
   * (See "The cull box" in `design/graphics-system.md`.)
   * @param frame - The frame being rendered
   * @return `true` to skip the pass, `false` to do it
   */
  public keepFeatures(frame: RenderFrame): boolean {
    // (A held frame keeps features even if they were marked dirty since: their pass is still to come.)
    if (!frame.changedFor(this.id) && (frame.held || this._currentBox === frame.cullBox)) {
      this._keptFrame = frame.id;
      return true;
    }
    this._currentBox = frame.cullBox;
    this._passFrame = frame.id;
    this._sortedBox = frame.viewBox;   // a pass sorts whatever it puts off by this frame's view
    return false;
  }


  /**
   * Whether the layer kept its features as they were in the given frame (see `keepFeatures`).
   * @param frame - The frame to ask about
   * @return `true` if the layer skipped its pass in that frame
   */
  public keptFeatures(frame: RenderFrame): boolean {
    return this._keptFrame === frame.id;
  }


  /**
   * Make invisible any Features that were not seen during the current pass, and end the pass.
   * Features that haven't been seen for `KEEP_UNSEEN_PASSES` passes are destroyed.
   * @param frame - The frame being rendered
   */
  public cull(frame: RenderFrame): void {
    this._catchingUp = false;    // (see `_gatherExtents`)

    // Data that was replaced or removed, and that this frame's gathering didn't find again
    for (const feature of this._unconfirmed) {
      if (this.retained.has(feature.id)) continue;
      feature.visible = false;
      this._waitingInView.delete(feature);
      this._waitingOutside.delete(feature);
    }
    this._unconfirmed.clear();

    if (this._keptFrame === frame.id) return;   // the features are as the last pass left them

    // If `render()` returned before `keepFeatures()` (the layer is off, or zoomed out too far),
    // everything gets hidden below, so the features aren't current for any box.
    if (this._passFrame !== frame.id) {
      this._currentBox = null;
    }

    const pass = this._pass++;
    for (const [featureID, feature] of this.features) {
      const seenPass = this.retained.get(featureID);
      if (seenPass === pass) continue;

      // Can't see it currently, make it invisible
      feature.visible = false;

      // Haven't seen it in a while, remove completely
      if (seenPass !== undefined && pass - seenPass > KEEP_UNSEEN_PASSES) {
        feature.destroy();
      }
    }

    this._cullDue = false;    // (what the box left behind is hidden now too)
    this.batches.removeEmpty();
  }


  /**
   * Whether the cull box moved without a pass (see `_gatherExtents`), and what it left behind is
   * still to be hidden (`cullLater`).
   * @return `true` if there's culling to do
   */
  public get cullDue(): boolean {
    return this._cullDue;
  }


  /**
   * Culls what the cull box left behind when it moved without a pass: hides the features that
   * aren't in the box anymore, and destroys the ones that have been hidden for a while
   * (`_forgetHidden`). They're outside the view, so nobody sees them meanwhile: the scene calls
   * this when a frame has time to spare, after every layer has rendered, and not on a frame that
   * was busy making what's in view. (SGI Performer's CULL, as a stage of its own.)
   */
  public cullLater(): void {
    const box = this._currentBox;
    this._cullDue = false;
    if (!box) return;    // a pass is coming, and culls everything

    // A feature stays while a pass would gather its data in the box (`_gatheredInBox`): by the
    // data's whole shape, so every part of a long line (a photo sequence) that reaches in anywhere.
    const reaches = (feature: AbstractPixiFeature): boolean => !!feature.geometry?.world?.extent.intersects(box);
    const dataReaches = new Map<DataID, boolean>();
    const anyReaches = (dataID: DataID): boolean => {
      let any = dataReaches.get(dataID);
      if (any === undefined) {
        any = false;
        for (const featureID of this._dataHasFeature.get(dataID) ?? []) {
          const other = this.features.get(featureID);
          if (other && reaches(other)) {
            any = true;
            break;
          }
        }
        dataReaches.set(dataID, any);
      }
      return any;
    };

    for (const feature of this.features.values()) {
      if (!feature.visible || reaches(feature)) continue;

      if (this._gatheredInBox(feature, box, anyReaches)) continue;

      feature.visible = false;
      this._waitingInView.delete(feature);   // (drawing it again could show it)
      this._waitingOutside.delete(feature);
    }
    this._forgetHidden();
    this.batches.removeEmpty();
  }


  /**
   * Whether a pass would gather a feature's data in the cull box (see `cullLater`): here, by the
   * data's own box, which is what a service's spatial cache finds it by, or if it has none, by
   * whether any feature of the data reaches in. A layer whose data's shape isn't its own (OSM
   * entities, whose shape belongs to a graph), or that draws data because of other data,
   * overrides this (the Rapid layer).
   * @param feature - A feature outside the box
   * @param box - The cull box
   * @param anyReaches - Whether any feature of some data reaches into the box
   * @return `true` if the feature belongs in the box
   */
  protected _gatheredInBox(feature: AbstractPixiFeature, box: Extent, anyReaches: (dataID: DataID) => boolean): boolean {
    const data = feature.data;
    if (!data) return false;
    const extent = data.geoms.world?.extent;
    return extent ? extent.intersects(box) : anyReaches(data.dataID);
  }


  /**
   * Destroys the features that have been hidden for more than `KEEP_HIDDEN_MOVES` moves of the
   * cull box (or passes). A pass does this for what it hasn't seen in a while (`cull()`), but
   * while the view only moves there are no passes, and what the box leaves behind would pile up.
   */
  protected _forgetHidden(): void {
    for (const [featureID, hiddenAt] of this._hiddenAt) {
      if (this._moves - hiddenAt <= KEEP_HIDDEN_MOVES) continue;
      this._hiddenAt.delete(featureID);    // (deleting from a Map while iterating over it is safe)
      this.features.get(featureID)?.destroy();
    }
  }


  /**
   * Says what a layer that draws data should gather on this frame, for a layer that gets its data
   * from a service by extent (photos, QA, Rapid datasets, custom data). Call it from `render()`,
   * after asking the service for the tiles that cover the view, and gather in the extents it
   * returns:
   * - **None,** when only the view moved inside the cull box (`keepFeatures`). Then it goes on
   *   drawing what waited, in view (`continueWaiting`).
   * - **Where data arrived, in the cull box,** on such a frame, if any did (`spatialChanged`).
   *   What's gathered belongs to the last pass, and the features of data that was replaced or
   *   removed are hidden if this gathering doesn't find them again (`cull()`).
   * - **The parts of the cull box that the last one didn't cover,** when only the view moved, out
   *   of the box (and where data arrived in it). The features in both boxes stay as they are, and what the box left behind is
   *   hidden later, when a frame has time (`cullLater`). There's no pass: `cull()` leaves the
   *   features alone, and what's gathered belongs to the last pass (`retainFeature`).
   * - **The cull box,** for a pass: anything else changed (a redraw request, a zoom, a class
   *   on the layer's own data), or there's no box yet.
   * @param frame - The frame being rendered
   * @param viewport - Pixi viewport to use for rendering
   * @return The extents to gather data in, in world coordinates
   */
  protected _gatherExtents(frame: RenderFrame, viewport: Viewport): Extent[] {
    const prevBox = this._currentBox;
    if (this.keepFeatures(frame)) {
      this.continueWaiting(frame, viewport);
      return this._takeArrivals(frame.cullBox);
    }

    // (`keepFeatures()` took the new box, and expects a pass.)
    if (prevBox && !frame.changedFor(this.id)) {
      this._keptFrame = frame.id;     // no pass: `cull()` leaves the features alone
      this._catchingUp = true;        // what's gathered belongs to the last pass (`cull()` ends this)
      this._cullDue = true;
      this._moves++;
      this.continueWaiting(frame, viewport);
      return [...extentMinus(frame.cullBox, prevBox), ...this._takeArrivals(frame.cullBox)];
    }

    this._arrivedBoxes = [];      // (the pass gathers everything)
    this._arrivedIDs.clear();
    this._moves++;
    this._forgetHidden();
    return [frame.cullBox];
  }


  /**
   * Takes what arrived since the layer last looked (`spatialChanged`), for a frame that's no pass:
   * the parts of the cull box where data arrived or moved from, to gather in. The features of data
   * that was replaced or removed are noted, to be hidden if the gathering doesn't find them again
   * (`cull()`). What's gathered belongs to the last pass.
   * @param box - The frame's cull box
   * @return The extents to gather data in, in world coordinates
   */
  protected _takeArrivals(box: Extent): Extent[] {
    const boxes = this._arrivedBoxes;
    const changedIDs = this._arrivedIDs;
    if (!boxes.length && !changedIDs.size) return [];

    this._arrivedBoxes = [];
    this._arrivedIDs = new Set<DataID>();
    this._catchingUp = true;    // (`cull()` ends this)

    for (const dataID of changedIDs) {
      for (const featureID of this._dataHasFeature.get(dataID) ?? []) {
        const feature = this.features.get(featureID);
        if (!feature) continue;
        this.retained.delete(featureID);
        this._unconfirmed.add(feature);
      }
    }

    const extents: Extent[] = [];
    for (const arrived of boxes) {
      if (arrived.intersects(box)) {
        extents.push(arrived.intersection(box));
      }
    }
    return extents;
  }


  /**
   * Whether the layer draws data from a spatial cache, and gathers it by extent (`_gatherExtents`):
   * then the scene tells it what changed there (`spatialChanged`). Here, from none: a layer
   * that gathers its data from a service says which caches the service keeps it in.
   * @param _spatialID - The cache's spatial ID
   * @return `true` if the layer draws data from it
   */
  public gathersFrom(_spatialID: SpatialID): boolean {
    return false;
  }


  /**
   * Data changed in a spatial cache (`SpatialSystem`'s `datachange`, which the scene passes on):
   * it arrived, was replaced or removed, or the cache was cleared. A layer that draws from the
   * cache (`gathersFrom`) notes where, and gathers there on its next frame without a pass
   * (`_gatherExtents`). A cleared cache means a pass.
   * @param spatialID - The cache's spatial ID
   * @param change - What changed in it
   * @return `true` if the layer has something to draw for it (the scene asks for a frame)
   */
  public spatialChanged(spatialID: SpatialID, change: SpatialChange): boolean {
    if (!this.enabled || !this.gathersFrom(spatialID)) return false;

    if (change.cleared) {
      this._currentBox = null;
      return true;
    }
    for (const box of change.boxes) {
      this._arrivedBoxes.push(new Extent([box.minX, box.minY], [box.maxX, box.maxY]));
    }
    for (const id of change.changedIDs) {
      this._arrivedIDs.add(makeDataID(spatialID, id));
    }
    return true;
  }


  /**
   * Gathers data in some extents, each item once.
   * @param extents - The extents (see `_gatherExtents`)
   * @param get - What gets the data in one extent (a service's getter)
   * @return The data, in the order found
   */
  protected _gatherIn<T>(extents: Extent[], get: (extent: Extent) => T[]): T[] {
    if (extents.length === 1) return get(extents[0]);

    const found = new Set<T>();
    for (const extent of extents) {
      for (const item of get(extent)) {
        found.add(item);
      }
    }
    return [...found];
  }


  /**
   * Returns what the layer did since the last call, and starts recording again.
   * `PixiScene.render()` calls this after each frame's pass, to put it in the frame's stats.
   * @return The work done
   */
  public takeWork(): LayerWork {
    const work = this.work;
    this.work = { created: 0, destroyed: 0, updated: 0, shown: 0, hidden: 0, steps: {} };
    return work;
  }


  /**
   * Records the time a step of `render()` took, for the frame's stats (`LayerFrameStats.steps`).
   * Call it after each step with the time the step began; it returns the time now, for the next one.
   * ```ts
   * let t = performance.now();
   * const data = this._gatherData();
   * t = this._endStep('gather', t);
   * this._renderLines(data);
   * t = this._endStep('lines', t);
   * ```
   * @param name - The step's name
   * @param since - When the step began (`performance.now()`)
   * @return The time now
   */
  protected _endStep(name: string, since: number): number {
    const now = performance.now();
    const steps = this.work.steps;
    steps[name] = (steps[name] ?? 0) + (now - since);
    return now;
  }


  /**
   * Add a feature to the layer cache.
   * @param feature - A Feature derived from `AbstractPixiFeature` (point, line, multipolygon)
   */
  public addFeature(feature: AbstractPixiFeature): void {
    this.features.set(feature.id, feature);
    this._hiddenAt.delete(feature.id);   // (a new feature is visible, whatever became of an earlier one with its ID)
    this.work.created++;
    if (feature.visible) {
      this._numVisible++;
    }
  }


  /**
   * Remove a Feature from the layer cache.
   * @param feature - A Feature derived from `AbstractPixiFeature` (point, line, multipolygon)
   */
  public removeFeature(feature: AbstractPixiFeature): void {
    this.unbindData(feature.id);
    this.retained.delete(feature.id);
    if (this.features.delete(feature.id) && feature.visible) {
      this._numVisible--;
    }
    this._waitingInView.delete(feature);
    this._waitingOutside.delete(feature);
    this._waitingForTexture.delete(feature);
    this.work.destroyed++;

    this._hiddenAt.delete(feature.id);
    this._parentOf.delete(feature);

    const box = this._indexedBoxes.get(feature);
    if (box) {
      this._featureIndex.remove(box);
      this._indexedBoxes.delete(feature);
    }
  }


  /**
   * A class was set or unset on some data (`PixiScene.setClass`, `unsetClass`): a hover, a
   * selection. A layer's pass picks that up for every feature it sees (`syncFeatureClasses`),
   * so if the data is this layer's, here the layer does its pass on the next frame (the scene
   * asks for one), though it may keep its features (`keepFeatures`). Data of another layer's
   * changes nothing here.
   * The OSM layer overrides this to remember the data, and draws just its features again on the
   * next frame, with no pass: then a hover costs what the hovered feature costs.
   * @param dataID - The data whose classes changed (it may be another layer's)
   */
  public classChanged(dataID: DataID): void {
    if (this._dataHasFeature.has(dataID)) {
      this._currentBox = null;
    }
  }


  /**
   * The mode changed (`Context.enter`). The frame that follows isn't a redraw of everything
   * (`gfx.requestFrame()`), so a layer that keeps its features, and draws something that depends
   * on the mode, overrides this to draw that again.
   */
  public modeChanged(): void {
    // nothing to do here
  }


  /**
   * Some of the layer's data changed (an edit), and nothing else did. The caller names everything
   * the change affects: what changed, was added or was removed, and whatever is drawn differently
   * because of it.
   * Here that marks the data's features dirty, which makes the layer do its next pass
   * (`dirtyData`). A layer that keeps its features overrides this to draw just that data again.
   * @param dataIDs - The data the change affects
   */
  public dataChanged(dataIDs: OneOrMore<DataID>): void {
    this.dirtyData(dataIDs);
  }


  /**
   * More of the layer's data arrived (a tile loaded), and nothing else changed. The caller names
   * what arrived and whatever it changes the look of.
   * Here that marks the data's features dirty, which makes the layer do its next pass
   * (`dirtyData`). A layer that keeps its features overrides this to make and draw just that
   * data, when its frames have time.
   * @param dataIDs - The data that arrived
   */
  public dataArrived(dataIDs: OneOrMore<DataID>): void {
    this.dirtyData(dataIDs);
  }


  /**
   * Finds the layer's feature under the pointer, the one drawn on top if there are several.
   * The scene asks this of a layer that said it finds its own (`PixiScene.setHitTester`, which
   * a layer that draws in batches does: see `useBatches`), in place of Pixi's hit test.
   *
   * This one asks the visible features near the pointer that it drew in batches (it keeps
   * an index of where they are), of the spatial IDs that the mode lets the pointer reach. Each
   * answers for itself (`AbstractPixiFeature.hitTest`), and the winner is the one drawn on top
   * (`featureOrder`). The OSM layer asks the editor's index instead (`PixiLayerOsm.hitTest`).
   * @param point - The pointer's place in the stage's coordinates (a pointer event's `global`)
   * @param world - The same place in world coordinates
   * @return The feature, or `null` if the pointer is over none of the layer's
   */
  public hitTest(point: PIXI.PointData, world: PIXI.PointData): AbstractPixiFeature | null {
    const context = this.context;
    const scene = this.scene;
    const viewport = context.viewport;

    if (!this._numVisible) return null;

    // How far from the box of its geometry a feature can be hit, in world coordinates
    const reach = (this._hitReach + HIT_REACH_MARGIN) * (2 ** (WORLD_ZOOM - viewport.transform.zoom));
    const box = { minX: world.x - reach, minY: world.y - reach, maxX: world.x + reach, maxY: world.y + reach };

    let best: AbstractPixiFeature | null = null;
    for (const found of this._featureIndex.search(box)) {
      const feature = found.feature;
      if (!feature.visible || !feature.allowInteraction) continue;
      if (!scene.isInteractive(found.spatialID)) continue;
      if (!feature.hitTest(point, world)) continue;
      if (!best || featureOrder(feature, best) > 0) {
        best = feature;
      }
    }
    return best;
  }


  /**
   * Keeps a feature's place in `_featureIndex`, for `hitTest`: its geometry's box, and the
   * spatial ID of the container it's drawn for. Nothing is written when neither changed (a
   * hover, a restyle). A feature with no geometry, or drawn for no spatial ID, isn't in it.
   * @param feature - The feature, just drawn
   * @param parent - The container it's drawn for
   */
  protected _indexFeature(feature: AbstractPixiFeature, parent: PIXI.Container): void {
    const index = this._featureIndex;
    const boxes = this._indexedBoxes;

    // The spatial ID: the one of the nearest container above `parent` that has one
    let spatialID: SpatialID | undefined;
    for (let c: PIXI.Container | null = parent; c && !spatialID; c = c.parent) {
      spatialID = this._spatialIDOf.get(c);
    }

    const extent = feature.geometry?.world?.extent;
    const old = boxes.get(feature);
    if (old && extent && old.spatialID === spatialID &&
      old.minX === extent.min[0] && old.minY === extent.min[1] && old.maxX === extent.max[0] && old.maxY === extent.max[1]
    ) return;   // where it was

    if (old) {
      index.remove(old);
      boxes.delete(feature);
    }
    if (extent && spatialID) {
      const box = {
        minX: extent.min[0], minY: extent.min[1], maxX: extent.max[0], maxY: extent.max[1],
        feature: feature, spatialID: spatialID
      };
      index.insert(box);
      boxes.set(feature, box);
    }
  }


  /**
   * Counts a feature of this layer being shown or hidden. `AbstractPixiFeature` calls this when
   * its `visible` changes, so the layer knows how many are visible without walking them all,
   * and since when a hidden one is hidden (see `_forgetHidden`).
   * @param feature - The feature
   * @param visible - Whether the feature is visible now
   */
  public visibilityChanged(feature: AbstractPixiFeature, visible: boolean): void {
    if (visible) {
      this._numVisible++;
      this.work.shown++;
      this._hiddenAt.delete(feature.id);
    } else {
      this._numVisible--;
      this.work.hidden++;
      this._hiddenAt.set(feature.id, this._moves);   // (see `_forgetHidden`)
    }
  }


  /**
   * How many of the layer's features are visible (not culled).
   * @return The number of visible features
   */
  public get numVisible(): number {
    return this._numVisible;
  }


  /**
   * Draws a feature again if it's dirty: in this frame, or in a later one if it can wait.
   * A layer calls this where it would call `feature.update(viewport)`, after assigning the
   * feature's data, style and label.
   *
   * - A feature in view is drawn now if the frame still has time (`frame.hasTime()`), or if the
   *   user asked for the frame (`frame.urgent`) and something about the feature itself changed.
   *   Otherwise it waits, and is drawn as it was meanwhile (after a zoom: at the old zoom's line
   *   widths), or not at all if it's new.
   * - A feature outside the view, in the cull box's padding, always waits: nobody sees it yet.
   *
   * `continueWaiting()` draws the ones that waited. A layer that calls this must call that too,
   * on the frames where it keeps its features (see `keepFeatures`; `_gatherExtents` does). The
   * scene calls it once more after every layer has rendered, for the features outside the view.
   * (See "A deadline on the frame" in `design/graphics-system.md`.)
   *
   * A layer that draws in batches (`useBatches`) gives the container it would put the feature
   * in. When the feature is drawn, it takes that container's batches (`placeInBatches()`), and
   * goes in the container only if it draws something itself (`drawsInContainer()`: markers a
   * batch has no shape for, a picture from another texture). Don't set `parentContainer` then.
   * Lines, polygons and points in one container are drawn in the order of their batches there
   * (see `LayerBatches`): give each kind a child container of its own (`_childContainer`) to draw
   * them in another order. (The OSM layer places its features itself, and gives none.)
   * @param feature - The feature to draw again
   * @param frame - The frame being rendered
   * @param viewport - Pixi viewport to use for rendering
   * @param parent - The container whose batches it's drawn in, and where it goes if it draws itself
   */
  public updateFeature(feature: AbstractPixiFeature, frame: RenderFrame, viewport: Viewport, parent?: PIXI.Container): void {
    if (parent) {
      this._parentOf.set(feature, parent);
    }
    if (!feature.dirty) return;

    const extent = feature.geometry?.world?.extent;
    const inView = !extent || extent.intersects(frame.viewBox);

    const mustNow = frame.urgent && !feature.onlyTransformDirty;

    if (inView && (mustNow || frame.hasTime())) {
      this._waitingInView.delete(feature);
      this._waitingOutside.delete(feature);
      this._drawFeature(feature, frame, viewport);
    } else if (inView) {
      this._waitingOutside.delete(feature);
      this._waitingInView.add(feature);
    } else {
      this._waitingInView.delete(feature);
      this._waitingOutside.add(feature);
    }
  }


  /**
   * Draws again the features that `updateFeature()` put off, while the frame has time.
   * At least a few are drawn on every call, so the work always gets done.
   * @param frame - The frame being rendered
   * @param viewport - Pixi viewport to use for rendering
   * @param outside - Whether to go on to the features outside the view, once the ones in view are done
   */
  public continueWaiting(frame: RenderFrame, viewport: Viewport, outside: boolean = false): void {
    this._sortWaiting(frame);

    const inView = this._waitingInView;
    const notInView = this._waitingOutside;
    if (!inView.size && !notInView.size) return;

    const lastPass = this._pass - 1;
    let count = 0;
    for (const queue of (outside ? [inView, notInView] : [inView])) {
      for (const feature of queue) {
        if (count >= MIN_WAITING_PER_FRAME && !frame.hasTime()) return;
        queue.delete(feature);   // (deleting from a Set while iterating over it is safe)

        // Skip what the last pass didn't see (it was culled since). If it comes back, it's still dirty.
        if (this.retained.get(feature.id) !== lastPass) continue;
        if (!feature.dirty) continue;

        this._drawFeature(feature, frame, viewport);
        count++;
      }
    }
  }


  /**
   * Sorts the waiting work again if the view has moved since it was sorted: what waited outside
   * the view and is in view now comes first. It's a walk over everything that waits outside, so
   * it happens only when the view is somewhere else, and then only now and then (`SORT_WAITING_MS`).
   * A layer with waiting work of its own overrides this, and sorts that too when this says so.
   * @param frame - The frame being rendered
   * @return `true` if the work was sorted again
   */
  protected _sortWaiting(frame: RenderFrame): boolean {
    if (this._sortedBox?.equals(frame.viewBox)) return false;              // the view hasn't moved
    if (frame.time - this._sortedTime < SORT_WAITING_MS) return false;    // it has, but we just looked

    this._sortedBox = frame.viewBox;
    this._sortedTime = frame.time;

    const inView = this._waitingInView;
    const notInView = this._waitingOutside;
    for (const feature of notInView) {
      const extent = feature.geometry?.world?.extent;
      if (!extent || extent.intersects(frame.viewBox)) {
        notInView.delete(feature);   // (deleting from a Set while iterating over it is safe)
        inView.add(feature);
      }
    }
    return true;
  }


  /**
   * Draws a dirty feature, and counts what that will cost in the frame's DRAW phase against the
   * frame's time (see `RenderFrame.drawDebt`).
   * @param feature - The feature to draw
   * @param frame - The frame being rendered
   * @param viewport - Pixi viewport to use for rendering
   */
  protected _drawFeature(feature: AbstractPixiFeature, frame: RenderFrame, viewport: Viewport): void {
    const drawMs = feature.onlyTransformDirty ? DRAW_MS_PER_REDRAW : DRAW_MS_PER_NEW;
    const parent = this._parentOf.get(feature);    // (for a layer that draws in batches, see `updateFeature`)

    if (parent) {
      feature.placeInBatches(this.useBatches ? this.batches : null, parent);
    }
    feature.update(viewport);
    frame.drawDebt += drawMs;
    if (feature.hitReach > this._hitReach) {
      this._hitReach = feature.hitReach;
    }
    if (parent) {
      feature.parentContainer = feature.drawsInContainer() ? parent : null;   // (a point finds out as it's drawn)
      this._indexFeature(feature, parent);
    }

    // Still dirty? Then it's drawn without a texture that hasn't loaded yet (an icon, see
    // `PixiFeaturePoint.updateStyle`). `texturesLoaded()` draws it again when one arrives.
    if (feature.dirty) {
      this._waitingForTexture.add(feature);
    } else {
      this._waitingForTexture.delete(feature);
    }
  }


  /**
   * A texture has loaded (see `PixiScene.texturesLoaded`). The features that were drawn without
   * one go back to waiting, and `continueWaiting()` draws them again over the next frames.
   * (Whichever texture it was: a feature still without its own waits for the next one.)
   */
  public texturesLoaded(): void {
    const viewBox = this._sortedBox;
    for (const feature of this._waitingForTexture) {
      const extent = feature.geometry?.world?.extent;
      const inView = !extent || !viewBox || extent.intersects(viewBox);
      (inView ? this._waitingInView : this._waitingOutside).add(feature);
    }
    this._waitingForTexture.clear();
  }


  /**
   * How many features are waiting to be drawn again.
   * @return The number of features that `updateFeature()` put off
   */
  public get numWaiting(): number {
    return this._waitingInView.size + this._waitingOutside.size;
  }


  /**
   * How many features in view are waiting to be drawn again.
   * @return The number of features in view that `updateFeature()` put off
   */
  public get numWaitingInView(): number {
    return this._waitingInView.size;
  }


  /**
   * Retain the feature for the current pass.
   * Features that are not retained may be automatically culled (made invisible) or removed.
   * @param feature - A Feature derived from `AbstractPixiFeature` (point, line, multipolygon)
   * @param frame - The frame being rendered
   */
  public retainFeature(feature: AbstractPixiFeature, frame: RenderFrame): void {
    if (feature.lod > 0) {
      feature.visible = true;
    }
    // If in user's view, retain it regardless of whether it's actually visible.
    // We want to avoid continuously creating invisible things just to dispose of them a few frames later.
    // For example points when zoomed out far.
    // (A feature made after the pass, by a layer catching up on what waited, belongs to that pass.)
    this.retained.set(feature.id, this._catchingUp ? this._pass - 1 : this._pass);
    if (this._hiddenAt.size) {
      this._hiddenAt.delete(feature.id);   // wanted, even if it isn't shown at this zoom
    }
  }


  /**
   * Adds (or replaces) a data binding from featureID to a dataID
   * @param featureID - featureID  (e.g. 'osm-w-123-fill')
   * @param dataID - dataID     (e.g. 'w-123')
   */
  public bindData(featureID: FeatureID, dataID: DataID): void {
    // Already bound to this data: done. (Unbinding first would drop the data's parent and child
    // links, when this is its only feature.)
    if (this._featureHasData.get(featureID) === dataID) return;

    this.unbindData(featureID);

    let featureSet = this._dataHasFeature.get(dataID);
    if (!featureSet) {
      featureSet = new Set<FeatureID>();
      this._dataHasFeature.set(dataID, featureSet);
    }
    featureSet.add(featureID);

    this._featureHasData.set(featureID, dataID);
  }


  /**
   * Removes the data binding for a given featureID
   * @param featureID - featureID  (e.g. 'osm-w-123-fill')
   */
  public unbindData(featureID: FeatureID): void {
    const dataID = this._featureHasData.get(featureID);
    if (!dataID) return;

    const featureSet = this._dataHasFeature.get(dataID);
    if (featureSet) {
      featureSet.delete(featureID);

      // If no features are bound to this data anymore, remove all references to it.
      if (!featureSet.size) {
        this._dataHasFeature.delete(dataID);
        this._parentHasChildren.delete(dataID);
        this._childHasParents.delete(dataID);
        // Note that we don't touch the data classes here..
        // e.g. if a selected feature leaves the scene and comes back later, it's still selected!
      }
    }

    this._featureHasData.delete(featureID);
  }


  /**
   * Adds a mapping from parent data to child data.
   * @param parentID - dataID of the parent (e.g. 'r123')
   * @param childIDs - dataIDs of the children to add (e.g. 'w123')
   */
  public addChildData(parentID: DataID, childIDs: OneOrMore<DataID>): void {
    let childSet = this._parentHasChildren.get(parentID);
    if (!childSet) {
      childSet = new Set<DataID>();
      this._parentHasChildren.set(parentID, childSet);
    }

    for (const childID of utilIterable(childIDs)) {
      childSet.add(childID);

      let parentSet = this._childHasParents.get(childID);
      if (!parentSet) {
        parentSet = new Set<DataID>();
        this._childHasParents.set(childID, parentSet);
      }
      parentSet.add(parentID);
    }
  }


  /**
   * Removes mapping from parent data to child data.
   * @param parentID - dataID of the parent (e.g. 'r123')
   * @param childIDs - dataIDs of the children to remove (e.g. 'w123')
   */
  public removeChildData(parentID: DataID, childIDs: OneOrMore<DataID>): void {
    const childSet = this._parentHasChildren.get(parentID);
    if (childSet) {
      for (const childID of utilIterable(childIDs)) {
        childSet.delete(childID);
      }
      if (!childSet.size) {
        this._parentHasChildren.delete(parentID);
      }
    }

    for (const childID of utilIterable(childIDs)) {
      const parentSet = this._childHasParents.get(childID);
      if (parentSet) {
        parentSet.delete(parentID);
        if (!parentSet.size) {
          this._childHasParents.delete(childID);
        }
      }
    }
  }


  /**
   * Removes all child dataIDs for the given parent dataID
   * @param parentID - dataID (e.g. 'r123')
   */
  public clearChildData(parentID: DataID): void {
    const childSet = this._parentHasChildren.get(parentID);
    if (childSet) {
      this.removeChildData(parentID, [...childSet]);   // a copy: removing empties the set while it's read
    }
  }


  /**
   * Recursively get a result `Set` including the given dataID and all dataIDs in the child hierarchy.
   * @param dataID - dataID (e.g. 'r123')
   * @param result - `Set` containing the results (e.g. ['r123','w123','n123'])
   * @returns `Set` including the dataID and all dataIDs in the child hierarchy
   */
  public getSelfAndDescendants(dataID: DataID, result?: Set<DataID>): Set<DataID> {
    if (result instanceof Set) {
      result.add(dataID);
    } else {
      result = new Set<DataID>([dataID]);
    }

    const childSet = this._parentHasChildren.get(dataID) ?? new Set<DataID>();
    for (const childID of childSet) {
      if (!result.has(childID)) {
        this.getSelfAndDescendants(childID, result);
      }
    }

    return result;
  }


  /**
   * Recursively get a result `Set` including the given dataID and all dataIDs in the parent hierarchy
   * @param dataID - dataID (e.g. 'n123')
   * @param result - `Set` containing the results (e.g. ['n123','w123','r123'])
   * @returns `Set` including the dataID and all dataIDs in the parent hierarchy
   */
  public getSelfAndAncestors(dataID: DataID, result?: Set<DataID>): Set<DataID> {
    if (result instanceof Set) {
      result.add(dataID);
    } else {
      result = new Set<DataID>([dataID]);
    }

    const parentSet = this._childHasParents.get(dataID) ?? new Set<DataID>();
    for (const parentID of parentSet) {
      if (!result.has(parentID)) {
        this.getSelfAndAncestors(parentID, result);
      }
    }

    return result;
  }


  /**
   * Get a result `Set` including the dataID and all sibling dataIDs in the parent-child hierarchy
   * @param dataID - `String` dataID (e.g. 'n123')
   * @param result - `Set` containing the results (e.g. ['n121','n122','n123','n124'])
   * @returns `Set` including the dataID and all dataIDs adjacent in the parent-child hierarchy
   */
  public getSelfAndSiblings(dataID: DataID, result?: Set<DataID>): Set<DataID> {
    if (result instanceof Set) {
      result.add(dataID);
    } else {
      result = new Set<DataID>([dataID]);
    }

    const parentSet = this._childHasParents.get(dataID) ?? new Set<DataID>();
    for (const parentID of parentSet) {
      const siblingIDs = this._parentHasChildren.get(parentID) ?? new Set<DataID>();
      for (const siblingID of siblingIDs) {
        result.add(siblingID);
      }
    }

    return result;
  }


  /**
   * Finds data drawn on this layer by its dataID, e.g. to select it again after undo.
   * Only data that has been drawn can be found.
   * @param dataID - dataID to look for
   * @returns the data, or `undefined` if it isn't drawn on this layer
   */
  public getData(dataID: DataID): AbstractData | undefined {
    for (const featureID of this._dataHasFeature.get(dataID) ?? []) {
      const data = this.features.get(featureID)?.data;
      if (data) return data;
    }
  }


  /**
   * This updates the feature's classes (e.g. 'select', 'hover', etc.) to match the Scene's classes
   * for the data bound to it.
   *
   * Counterintuitively, the Scene needs to be the source of truth for these classes,
   * because a Feature can be 'selected' or 'drawing' even before it has been created, or after destroyed.
   *
   * Syncing these classes will dirty the feature if the it causes a change.
   * Therefore this should be called after the Feature has been created, but before any updates happen.
   *
   * @param feature - A Feature derived from `AbstractPixiFeature` (point, line, multipolygon)
   */
  public syncFeatureClasses(feature: AbstractPixiFeature): void {
    const featureID = feature.id;
    const dataID = this._featureHasData.get(featureID);
    if (!dataID) return;

    const layerClasses = this.scene.getClasses(dataID);
    const featureClasses = feature.classes;

    for (const classID of featureClasses) {
      if (layerClasses.has(classID)) continue;  // no change
      feature.unsetClass(classID);              // remove extra class from feature
    }
    for (const classID of layerClasses) {
      if (featureClasses.has(classID)) continue;  // no change
      feature.setClass(classID);                  // add missing class to feature
    }

    // Trying to document all the supported pseudoclasses here:
    //
    // 'drawing':  removes the hitarea, and avoids hover, e.g. it prevents snapping
    // 'highlight':  adds a blue glowfilter
    // 'hover':  adds a yellow glowfilter
    // 'select':  adds a dashed line halo
    // 'selectphoto':  styling for the currently selected photo
  }


  /**
   * Mark all features on this layer as `dirty`.
   * During the next "app" pass, dirty features will be rebuilt.
   * (So the layer does that pass, whatever the frame is for: see `keepFeatures`.)
   */
  public dirtyLayer(): void {
    this._currentBox = null;
    for (const feature of this.features.values()) {
      feature.dirty = true;
    }
  }

  /**
   * Mark all features on this layer as needing to be drawn again for a new zoom or rotation.
   * Unlike `dirtyLayer()`, this says that the features themselves haven't changed, so a layer
   * that checks `feature.needsStyle` doesn't work out their styles again.
   */
  public dirtyTransform(): void {
    this._currentBox = null;
    for (const feature of this.features.values()) {
      feature.dirtyTransform();
    }
  }

  /**
   * Mark specific features features as `dirty`
   * During the next "app" pass, dirty features will be rebuilt.
   * @param featureIDs - featureIDs to set dirty
   */
  public dirtyFeatures(featureIDs: OneOrMore<FeatureID>): void {
    this._currentBox = null;
    for (const featureID of utilIterable(featureIDs)) {
      const feature = this.features.get(featureID);
      if (feature) {
        feature.dirty = true;
      }
    }
  }

  /**
   * Mark any features bound to a given dataID as `dirty`
   * During the next "app" pass, dirty features will be rebuilt.
   * @param dataIDs - dataIDs to set dirty
   */
  public dirtyData(dataIDs: OneOrMore<DataID>): void {
    for (const dataID of utilIterable(dataIDs)) {
      const featureIDs = this._dataHasFeature.get(dataID);
      if (featureIDs) {
        this.dirtyFeatures(featureIDs);
      }
    }
  }

}
