import { AbstractPixiLayer } from './AbstractPixiLayer.ts';
import { PixiFeaturePoint } from './PixiFeaturePoint.ts';

import type { MatchedStyle } from '../core/StyleSystem.ts';
import type { PixiScene } from './PixiScene.ts';
import type { RenderFrame } from './RenderFrame.ts';
import type { Extent, Viewport } from '@rapid-sdk/math';

const MINZOOM = 12;


/**
 * This class renders OpenStreetMap note markers.
 */
export class PixiLayerOsmNotes extends AbstractPixiLayer {

  /**
   * @param  scene - The Scene that owns this Layer
   */
  public constructor(scene: PixiScene) {
    super(scene);
    this.id = 'osm-notes';
    this.useBatches = true;
  }


  /**
   * Whether the Layer's service exists
   * @return  `true` if the OSM service is registered
   */
  public get supported() {
    return !!this.context.services.osm;
  }


  /**
   * Whether the user has chosen to see the Layer
   * Make sure to start the service first.
   * @return  `true` if the layer is enabled
   */
  public get enabled() {
    return this._enabled;
  }
  /** Enables or disables this layer; starts the OSM service when enabling.
   * @param val - `true` to enable the layer, `false` to disable it
   */
  public set enabled(val) {
    if (!this.supported) {
      val = false;
    }

    if (val === this._enabled) return;  // no change
    this._enabled = val;

    const context = this.context;
    const osm = context.services.osm;
    if (val && osm) {
      osm.startAsync()
        .then(() => this.gfx.immediateRedraw(this.id));
    }
  }


  /**
   * Renders the OSM note markers for this frame.
   * @param  frame    -  The frame being rendered
   * @param  viewport -  Pixi viewport to use for rendering
   * @param extents - Where to gather the data, in world coordinates (see `_gatherExtents`)
   */
  public renderMarkers(frame: RenderFrame, viewport: Viewport, extents: Extent[]): void {
    const osm = this.context.services.osm;
    if (!osm?.started) return;

    const parentContainer = this._spatialContainer('qa', this.id);
    const notes = this._gatherIn(extents, extent => osm.getNotes(extent));

    for (const d of notes) {
      const dataID = d.id;
      const part = d.geoms.parts[0];
      if (!part?.world || part?.type !== 'Point') continue;

      const featureID = `${this.layerID}-${dataID}`;
      let feature = this.features.get(featureID);

      // Create feature if necessary..
      if (!feature) {
        feature = new PixiFeaturePoint(this, featureID);
      }

      // If data has changed, replace it.. (Changed data is a new object: data isn't changed in place.)
      if (feature.data !== d || feature.geometry !== part) {
        feature.geometry = part;
        feature.data = d;
      }

      this.syncFeatureClasses(feature);

      if (feature.dirty) {
        let color = 0xff3300;  // open (red)
        let iconName = 'rapid-icon-close';
        if (d.props.status === 'closed') {
          color = 0x55dd00;  // closed (green)
          iconName = 'rapid-icon-apply';
        }
        if (d.isNew) {
          color = 0xffee00;  // new (yellow)
          iconName = 'rapid-icon-plus';
        }

        // Override 'y' anchor for better centering within the note balloon
        const style: Partial<MatchedStyle> = {
          marker: { color: color, image: 'osmnote', anchor: [0.5, 0.65] },
          icon: { color: 0x000000, image: iconName, anchor: [0.5, 0.65] }
        };

        feature.style = style;
      }

      this.updateFeature(feature, frame, viewport, parentContainer);
      this.retainFeature(feature, frame);
    }
  }


  /**
   * Whether this layer draws data from a spatial cache (see `AbstractPixiLayer.gathersFrom`):
   * the OSM notes.
   * @param spatialID - The cache's spatial ID
   * @return `true` if this layer draws data from it
   */
  public override gathersFrom(spatialID: SpatialID): boolean {
    return spatialID === 'osm-notes';
  }


  /**
   * Render any data we have, and schedule fetching more of it to cover the view
   * @param  frame    -  The frame being rendered
   * @param  viewport -  Pixi viewport to use for rendering
   */
  public render(frame: RenderFrame, viewport: Viewport): void {
    const osm = this.context.services.osm;
    const viewZoom = viewport.transform.zoom;
    if (!this.enabled || !osm?.started || viewZoom < MINZOOM) return;

    osm.loadNotes();
    const extents = this._gatherExtents(frame, viewport);
    if (!extents.length) return;   // only the view moved, inside the cull box the last pass covered
    this.renderMarkers(frame, viewport, extents);
  }

}

